   729→// getSessionsBranchTree returns the tree object for the entire/sessions branch.
   730→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
   731→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   732→	ref, err := s.repo.Reference(refName, true)
   733→	if err != nil {
   734→		return nil, fmt.Errorf("sessions branch not found: %w", err)
   735→	}
   736→
   737→	commit, err := s.repo.CommitObject(ref.Hash())
   738→	if err != nil {
   739→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   740→	}
   741→
   742→	tree, err := commit.Tree()
   743→	if err != nil {
   744→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   745→	}
   746→
   747→	return tree, nil
   748→}
