    51→// getCheckpointsForSession returns all checkpoints for a session ID.
    52→func (s *ManualCommitStrategy) getCheckpointsForSession(sessionID string) ([]CheckpointInfo, error) {
    53→	all, err := s.listCheckpoints()
    54→	if err != nil {
