   687→// GetTranscript retrieves the transcript for a specific checkpoint ID.
   688→func (s *GitStore) GetTranscript(ctx context.Context, checkpointID string) ([]byte, error) {
   689→	result, err := s.ReadCommitted(ctx, checkpointID)
   690→	if err != nil {
   691→		return nil, err
   692→	}
   693→	if result == nil {
   694→		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
   695→	}
   696→	if len(result.Transcript) == 0 {
   697→		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
   698→	}
   699→	return result.Transcript, nil
   700→}
