   829→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
   830→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
   831→	// Get repository config (includes local settings)
   832→	cfg, err := repo.Config()
   833→	if err == nil {
