   548→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   549→// Returns nil, nil if the checkpoint doesn't exist.
   550→//
   551→
   552→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID string) (*ReadCommittedResult, error) {
   553→	_ = ctx // Reserved for future use
   554→
   555→	tree, err := s.getSessionsBranchTree()
   556→	if err != nil {
   557→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   558→	}
   559→
   560→	checkpointPath := paths.CheckpointPath(checkpointID)
   561→	checkpointTree, err := tree.Tree(checkpointPath)
   562→	if err != nil {
   563→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   564→	}
   565→
   566→	result := &ReadCommittedResult{}
   567→
   568→	// Read metadata.json
   569→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   570→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   571→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   572→			json.Unmarshal([]byte(content), &result.Metadata)
   573→			result.Metadata.Strategy = paths.NormalizeStrategyName(result.Metadata.Strategy)
   574→		}
   575→	}
   576→
   577→	// Read transcript (try current format first, then legacy)
   578→	if file, fileErr := checkpointTree.File(paths.TranscriptFileName); fileErr == nil {
   579→		if content, contentErr := file.Contents(); contentErr == nil {
   580→			result.Transcript = []byte(content)
   581→		}
   582→	} else if file, fileErr := checkpointTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
   583→		if content, contentErr := file.Contents(); contentErr == nil {
   584→			result.Transcript = []byte(content)
   585→		}
   586→	}
   587→
   588→	// Read prompts
   589→	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
   590→		if content, contentErr := file.Contents(); contentErr == nil {
   591→			result.Prompts = content
   592→		}
   593→	}
   594→
   595→	// Read context
   596→	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
   597→		if content, contentErr := file.Contents(); contentErr == nil {
   598→			result.Context = content
   599→		}
   600→	}
   601→
   602→	// Read archived sessions if this is a multi-session checkpoint
   603→	if result.Metadata.SessionCount > 1 {
   604→		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount)
   605→	}
   606→
   607→	return result, nil
   608→}
   609→
   610→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   611→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   612→//
   613→
   614→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   615→	_ = ctx // Reserved for future use
   616→
   617→	tree, err := s.getSessionsBranchTree()
   618→	if err != nil {
   619→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   620→	}
   621→
   622→	var checkpoints []CommittedInfo
   623→
   624→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   625→	for _, bucketEntry := range tree.Entries {
   626→		if bucketEntry.Mode != filemode.Dir {
   627→			continue
   628→		}
   629→		// Bucket should be 2 hex chars
   630→		if len(bucketEntry.Name) != 2 {
   631→			continue
   632→		}
   633→
   634→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   635→		if treeErr != nil {
   636→			continue
   637→		}
   638→
   639→		// Each entry in the bucket is the remaining part of the checkpoint ID
   640→		for _, checkpointEntry := range bucketTree.Entries {
   641→			if checkpointEntry.Mode != filemode.Dir {
   642→				continue
   643→			}
   644→
   645→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   646→			if cpTreeErr != nil {
   647→				continue
   648→			}
   649→
   650→			// Reconstruct checkpoint ID: <bucket><remaining>
   651→			checkpointID := bucketEntry.Name + checkpointEntry.Name
   652→
   653→			info := CommittedInfo{
   654→				CheckpointID: checkpointID,
   655→			}
   656→
   657→			// Get details from metadata file
   658→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   659→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   660→					var metadata CommittedMetadata
   661→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   662→						info.SessionID = metadata.SessionID
   663→						info.CreatedAt = metadata.CreatedAt
   664→						info.CheckpointsCount = metadata.CheckpointsCount
   665→						info.FilesTouched = metadata.FilesTouched
   666→						info.Agent = metadata.Agent
   667→						info.IsTask = metadata.IsTask
   668→						info.ToolUseID = metadata.ToolUseID
   669→						info.SessionCount = metadata.SessionCount
   670→						info.SessionIDs = metadata.SessionIDs
   671→					}
   672→				}
   673→			}
   674→
   675→			checkpoints = append(checkpoints, info)
   676→		}
   677→	}
   678→
   679→	// Sort by time (most recent first)
   680→	sort.Slice(checkpoints, func(i, j int) bool {
   681→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   682→	})
   683→
   684→	return checkpoints, nil
   685→}
