   531→// This mirrors strategy.SubagentCheckpoint but avoids import cycles.
   532→type incrementalCheckpointData struct {
   533→	Type      string          `json:"type"`
   534→	ToolUseID string          `json:"tool_use_id"`
   535→	Timestamp time.Time       `json:"timestamp"`
   536→	Data      json.RawMessage `json:"data"`
   537→}
