   539→// taskCheckpointData represents a final task checkpoint.
   540→// This mirrors strategy.TaskCheckpoint but avoids import cycles.
   541→type taskCheckpointData struct {
   542→	SessionID      string `json:"session_id"`
   543→	ToolUseID      string `json:"tool_use_id"`
   544→	CheckpointUUID string `json:"checkpoint_uuid"`
