   730→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
   731→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   732→	ref, err := s.repo.Reference(refName, true)
   733→	if err != nil {
