   548→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   549→// Returns nil, nil if the checkpoint doesn't exist.
   550→//
   551→
   552→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID string) (*ReadCommittedResult, error) {
   553→	_ = ctx // Reserved for future use
   554→
   555→	tree, err := s.getSessionsBranchTree()
   556→	if err != nil {
   557→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   558→	}
   559→
   560→	checkpointPath := paths.CheckpointPath(checkpointID)
   561→	checkpointTree, err := tree.Tree(checkpointPath)
   562→	if err != nil {
   563→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   564→	}
   565→
   566→	result := &ReadCommittedResult{}
   567→
   568→	// Read metadata.json
   569→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   570→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   571→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   572→			json.Unmarshal([]byte(content), &result.Metadata)
   573→			result.Metadata.Strategy = paths.NormalizeStrategyName(result.Metadata.Strategy)
   574→		}
   575→	}
   576→
   577→	// Read transcript (try current format first, then legacy)
   578→	if file, fileErr := checkpointTree.File(paths.TranscriptFileName); fileErr == nil {
   579→		if content, contentErr := file.Contents(); contentErr == nil {
   580→			result.Transcript = []byte(content)
   581→		}
   582→	} else if file, fileErr := checkpointTree.File(paths.TranscriptFileNameLegacy); fileErr == nil {
   583→		if content, contentErr := file.Contents(); contentErr == nil {
   584→			result.Transcript = []byte(content)
   585→		}
   586→	}
   587→
   588→	// Read prompts
   589→	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
   590→		if content, contentErr := file.Contents(); contentErr == nil {
   591→			result.Prompts = content
   592→		}
   593→	}
   594→
   595→	// Read context
   596→	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
   597→		if content, contentErr := file.Contents(); contentErr == nil {
   598→			result.Context = content
   599→		}
   600→	}
   601→
   602→	// Read archived sessions if this is a multi-session checkpoint
   603→	if result.Metadata.SessionCount > 1 {
   604→		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount)
   605→	}
   606→
   607→	return result, nil
   608→}
