   702→// ensureSessionsBranch ensures the entire/sessions branch exists.
   703→func (s *GitStore) ensureSessionsBranch() error {
   704→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   705→	_, err := s.repo.Reference(refName, true)
   706→	if err == nil {
   707→		return nil // Branch exists
   708→	}
   709→
   710→	// Create orphan branch with empty tree
   711→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
   712→	if err != nil {
   713→		return err
   714→	}
   715→
   716→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   717→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
   718→	if err != nil {
   719→		return err
   720→	}
   721→
   722→	newRef := plumbing.NewHashReference(refName, commitHash)
   723→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   724→		return fmt.Errorf("failed to set branch reference: %w", err)
   725→	}
   726→	return nil
   727→}
