   467→// AgentTranscriptPath returns the path to a subagent's transcript file.
   468→// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
   469→// as the main transcript.
   470→func AgentTranscriptPath(transcriptDir, agentID string) string {
   471→	return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
   472→}
